import{_ as e,o as l,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const x=JSON.parse('{"title":"ホットキーとマウス操作","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/hotkeys.md","filePath":"ja-JP/user-guide/hotkeys.md","lastUpdated":1790959149000}'),r={name:"ja-JP/user-guide/hotkeys.md"};function a(s,t,n,g,i,c){return l(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="ホットキーとマウス操作" tabindex="-1">ホットキーとマウス操作 <a class="header-anchor" href="#ホットキーとマウス操作" aria-label="Permalink to &quot;ホットキーとマウス操作&quot;">​</a></h1><p>Lertaro はキーボード優先の操作設計を採用しつつ、多彩なマウスジェスチャーと階層型クイックナビゲーションを提供します。固定キーを除き、すべてのグローバルおよびアプリ内ホットキーは <a href="./settings/hotkeys-page.html"><strong>設定 → ホットキー</strong></a> で自由にカスタマイズできます。</p><h2 id="_1-グローバルホットキー一覧" tabindex="-1">1. グローバルホットキー一覧 <a class="header-anchor" href="#_1-グローバルホットキー一覧" aria-label="Permalink to &quot;1. グローバルホットキー一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">機能・アクション</th><th style="text-align:left;">既定のキー</th><th style="text-align:left;">機能説明と操作の詳細</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>クイックウィンドウの表示/非表示</strong></td><td style="text-align:left;"><code>Ctrl</code> の 2 回連打</td><td style="text-align:left;">連打方式または通常の修飾キー組み合わせ（例: <code>Alt+Space</code>、<code>Win+Space</code> など）に変更可能です。連打は<strong>同じ</strong>修飾キーを 2 回押して <strong>100〜300 ms</strong> をおいて離す操作を指します。左右の <code>Ctrl</code> は別のキーであり、その間に他のキーを押すとカウントはやり直しになります。連打方式では修飾キー自体が吸収されないため、通常の <code>Ctrl</code>+<code>C</code> 系のショートカットはそのまま動作します。<strong>既定でメインウィンドウを開く</strong>を有効にすると、このキーでメインウィンドウを開き、初回表示時は一度だけ前面とフォーカスを処理します。表示中で非アクティブなら再アクティブ化し、すでにアクティブならもう一度押すと閉じます。自動的に最前面へ固定されることはありません。</td></tr><tr><td style="text-align:left;"><strong>クイックジャンプ（Quick Jump）</strong></td><td style="text-align:left;"><code>Ctrl+G</code></td><td style="text-align:left;">ファイルダイアログ内で、直前にファイラーやクイックパネルで開いていたフォルダーへ即座に移動。</td></tr><tr><td style="text-align:left;"><strong>クイックナビゲーションメニュー</strong></td><td style="text-align:left;">既定値なし</td><td style="text-align:left;">任意のグローバルショートカットで階層型クイックナビゲーションメニューを開けます。デスクトップや通常のアプリではデスクトップのコンテキストを使い、エクスプローラーやネイティブのファイルダイアログではアクティブなウィンドウのコンテキストを使います。通常の前景保護でグローバルホットキーが抑止される場合でも、ファイラーとファイルダイアログは許可されます。</td></tr><tr><td style="text-align:left;"><strong>次の項目を選択</strong></td><td style="text-align:left;"><code>Ctrl+N</code> または <code>↓</code></td><td style="text-align:left;">一覧の選択を下に移動。クイックパネルではグループをまたいで連続して移動できます。クイック起動パネルでは方向キーが見た目のグリッドに沿って動き、左右は行の境界を越え、上下は隣接する方向にある同じ列の最も近い項目を探します。グループをまたいで移動することもでき、その方向に同じ列の項目がどこにもない場合だけ現在の位置に留まります。クイック起動パネルが表示され検索語が空の場合、<code>Ctrl+N</code> で次のソースへ循環します。</td></tr><tr><td style="text-align:left;"><strong>前の項目を選択</strong></td><td style="text-align:left;"><code>Ctrl+P</code> または <code>↑</code></td><td style="text-align:left;">一覧の選択を上に移動。クイックパネルでもグループをまたいで連続して移動できます。クイック起動パネルでは方向キーが見た目のグリッドに沿って動き、左右は行の境界を越え、上下は隣接する方向にある同じ列の最も近い項目を探します。グループをまたいで移動することもでき、その方向に同じ列の項目がどこにもない場合だけ現在の位置に留まります。クイック起動パネルが表示され検索語が空の場合、<code>Ctrl+P</code> で前のソースへ循環します。</td></tr><tr><td style="text-align:left;"><strong>1〜9 番目の結果を開く</strong></td><td style="text-align:left;"><code>Ctrl</code> + <code>1</code>〜<code>9</code></td><td style="text-align:left;">修飾キーは変更可能。クイックウィンドウの結果横に数字バッジが表示され、即座に起動可能。数字は<strong>最初に見えている行からの</strong> N 番目の選択可能な行を意味するため、スクロールするとバッジの番号は振り直されます。<code>0</code> は割り当てられていません。クイック起動パネルだけが例外で、<code>1</code>〜<code>9</code>、<code>0</code>、<code>A</code>〜<code>Z</code> まで最大 36 タイルに割り当てられます。</td></tr><tr><td style="text-align:left;"><strong>アクションメニューを開く</strong></td><td style="text-align:left;"><code>Ctrl+O</code> または <code>→</code></td><td style="text-align:left;">選択中の項目のコンテキストアクション（パスのコピー、プロパティ、管理者実行、ファイル操作等）を展開。クイックウィンドウと、ファイルダイアログ<strong>外</strong>のインラインウィンドウで使えます。メインウィンドウでは同じメニューを右クリックまたは <code>Apps</code> キー（<code>Shift+F10</code>）で開きます。</td></tr><tr><td style="text-align:left;"><strong>選択項目で検索語を補完</strong></td><td style="text-align:left;"><code>Ctrl+Tab</code></td><td style="text-align:left;">選択項目の名前またはフルパスを検索ボックスに入力し、追加の絞り込みを容易にする。</td></tr><tr><td style="text-align:left;"><strong>QuickLook 即時プレビュー</strong></td><td style="text-align:left;"><code>Alt+P</code></td><td style="text-align:left;">プレビューパネルの開閉（画像、文書、音声・動画の即時再生、フォルダーツリー構造）。クイックウィンドウ・メインウィンドウ・クイックパネルで使え、インラインウィンドウでは使えません。プレビュー可能な行の中クリックでも同じパネルを開閉できます。</td></tr><tr><td style="text-align:left;"><strong>前の検索履歴語</strong></td><td style="text-align:left;"><code>Alt+Up</code></td><td style="text-align:left;">最近入力した検索キーワードを前に遡って表示。</td></tr><tr><td style="text-align:left;"><strong>次の検索履歴語</strong></td><td style="text-align:left;"><code>Alt+Down</code></td><td style="text-align:left;">最近入力した検索キーワードを後ろに進んで表示。</td></tr><tr><td style="text-align:left;"><strong>現在の履歴語を削除</strong></td><td style="text-align:left;"><code>Ctrl+Delete</code></td><td style="text-align:left;">現在表示されている検索キーワードを検索履歴から削除。</td></tr><tr><td style="text-align:left;"><strong>メインウィンドウを開く</strong></td><td style="text-align:left;"><code>Ctrl+F</code></td><td style="text-align:left;">現在入力中の検索キーワードを引き継いだまま、大画面のメイン検索ウィンドウを開く。</td></tr><tr><td style="text-align:left;"><strong>LocalSend 画面を開く</strong></td><td style="text-align:left;"><code>Ctrl+S</code></td><td style="text-align:left;">LocalSend 経由で他デバイスにファイルやテキストを送信する画面を開く。</td></tr><tr><td style="text-align:left;"><strong>ウィンドウを固定（ピン留め）</strong></td><td style="text-align:left;"><code>Ctrl+T</code></td><td style="text-align:left;">フォーカスを失ってもウィンドウを閉じずに維持（他アプリから文字をコピーして貼り付ける際に便利）。</td></tr><tr><td style="text-align:left;"><strong>クイックパネルの表示/非表示</strong></td><td style="text-align:left;"><code>Ctrl+F2</code></td><td style="text-align:left;">現在のアクティブウィンドウの横に、最近のファイル・お気に入り・ワークスペースを含むパネルを表示。</td></tr></tbody></table><h3 id="ファイルダイアログで検索欄が空の場合" tabindex="-1">ファイルダイアログで検索欄が空の場合 <a class="header-anchor" href="#ファイルダイアログで検索欄が空の場合" aria-label="Permalink to &quot;ファイルダイアログで検索欄が空の場合&quot;">​</a></h3><p>ネイティブのファイルダイアログにインライン検索ボックスが埋め込まれていて検索欄が空の場合、一覧にはまず「前回のディレクトリ」グループが表示されます。「インライン検索に現在開いているフォルダーを表示」が有効なら、対応ファイラーで現在開いているフォルダーをまとめた「現在開いているフォルダー」グループも表示されます。現在のファイルダイアログが開いているフォルダーは除外され、重複するパスは統合され、空のグループは表示されません。グループ見出しにはショートカットバッジも表示されません。この設定は既定で有効で、<a href="./settings/general.html"><strong>設定 → 一般 → システム</strong></a> から変更できます。この動作はファイルダイアログ内のインライン検索だけに適用され、クイックウィンドウとフルウィンドウには影響しません。</p><h3 id="インラインウィンドウの呼び出しとフォーカスの引き継ぎ" tabindex="-1">インラインウィンドウの呼び出しとフォーカスの引き継ぎ <a class="header-anchor" href="#インラインウィンドウの呼び出しとフォーカスの引き継ぎ" aria-label="Permalink to &quot;インラインウィンドウの呼び出しとフォーカスの引き継ぎ&quot;">​</a></h3><p>ネイティブのファイルダイアログにドッキングしたウィンドウは、意図的に<strong>キーボードを奪いません</strong>。フォーカスはダイアログに残るので、ダイアログ自身のファイル名欄へそのまま入力を続けられ、ウィンドウ側は検索語を反映します。キャレットを動かせる操作は次のとおりです。</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作</th><th style="text-align:left;">効果</th><th style="text-align:left;">条件</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>英数字を入力</strong></td><td style="text-align:left;">ウィンドウが呼び出され、最初に入力した 1 文字が検索ボックスに引き継がれ、その後のキー入力もそのまま流れ込みます</td><td style="text-align:left;">実際のキー入力のみが対象です。自動化ツールによる合成入力はそのまま素通しされ、コンテキストメニューやシステムメニューが開いている間は何も捕捉しません</td></tr><tr><td style="text-align:left;"><strong><code>Ctrl</code> の 2 回連打</strong>（または設定済みの呼び出しホットキー）</td><td style="text-align:left;">キャレットをウィンドウ自身の検索ボックスへ入れます。検索ボックスがすでにキャレットを持っていて検索語が空の場合は、代わりに検索語をクリアし、ウィンドウを開いたままフォーカスをダイアログの欄へ返します</td><td style="text-align:left;">他の場所と同じホットキーです。<a href="./settings/hotkeys-page.html"><strong>設定 → ホットキー</strong></a> で割り当てを変えれば、この引き継ぎも一緒に変わります。ブラックリストや全画面で通常ならグローバルホットキーが抑止される場合でも、ファイルダイアログは許可されたままです</td></tr><tr><td style="text-align:left;"><strong><code>Escape</code></strong></td><td style="text-align:left;"><strong>ダイアログ</strong>がキーボードを持っている間はウィンドウを閉じます。<strong>ウィンドウ</strong>が持っている間は検索語をクリアし、フォーカスをダイアログへ戻します（ファイルダイアログの場合）か、ウィンドウを閉じます（通常のエクスプローラー上にドッキングしている場合）</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">空の欄で <strong><code>Backspace</code></strong></td><td style="text-align:left;"><code>Escape</code> とまったく同じように検索を終了します</td><td style="text-align:left;">ウィンドウがキャレットを持っている場合のみ。ダイアログがキーボードを持っている間は、このキーはウィンドウの検索語を編集するだけにとどまります</td></tr><tr><td style="text-align:left;">空の欄で <strong><code>Enter</code></strong></td><td style="text-align:left;"><code>Escape</code> と同じように検索を終了します</td><td style="text-align:left;">ウィンドウがキャレットを持っている場合のみ。ダイアログがキーボードを持っている間は、<code>Enter</code> は選択中のブラウズ行を開きます</td></tr><tr><td style="text-align:left;"><strong><code>Tab</code></strong></td><td style="text-align:left;">ダイアログ自身のコントロール移動に残り続けるため、ウィンドウへは呼び出しホットキーで移動してください</td><td style="text-align:left;"></td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>ファイルダイアログ内では、ウィンドウのアクションメニューを利用できません（<code>Ctrl+O</code>、<code>→</code>、右クリックはいずれも効かず、<code>Alt+P</code> のプレビューも提供されません）。マウスは行に対してそのまま使えます。<strong>左クリック</strong>で選択中の結果を開き、<strong><code>Ctrl</code>+クリック</strong>で管理者として開き、行を<strong>ドラッグアウト</strong>してダイアログ側に落とせ、<strong>ホバーするだけ</strong>で選択が動きます（ホストのファイラー側にも同じ選択が反映されます）。</p></div><h2 id="_2-検索ボックスのロゴとマウス操作" tabindex="-1">2. 検索ボックスのロゴとマウス操作 <a class="header-anchor" href="#_2-検索ボックスのロゴとマウス操作" aria-label="Permalink to &quot;2. 検索ボックスのロゴとマウス操作&quot;">​</a></h2><p>検索ボックス内の小さなロゴアイコンには、実用的なマウス操作が割り当てられています。</p><h3 id="クイックウィンドウでのロゴ操作" tabindex="-1">クイックウィンドウでのロゴ操作 <a class="header-anchor" href="#クイックウィンドウでのロゴ操作" aria-label="Permalink to &quot;クイックウィンドウでのロゴ操作&quot;">​</a></h3><ul><li><strong>左クリック</strong>：カーソル位置にコンテキストメニューを表示（メインウィンドウの表示、ホットキー切り替え、設定、バージョン情報、クリーン終了、終了）。「メインウィンドウの表示」は現在の検索語を引き継ぎます。</li><li><strong>左ドラッグ</strong>：画面上の検索バーの位置を自由に移動。<strong><code>Ctrl</code> キーを押しながらドラッグ</strong>すると、移動方向が<strong>垂直方向のみ</strong>に固定され、横位置のズレを防げます。</li><li><strong>右クリック</strong>：設定されたサイズを維持したまま、クイックウィンドウを画面中央の既定位置にリセット。</li><li><strong>中クリック</strong>：ウィンドウの「固定（ピン留め）」を切り替え。固定中はロゴが点灯します。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>クイックウィンドウが記憶する座標は、表示中のモニターに対する<strong>相対比率座標</strong>です。解像度や DPI スケーリングが異なる別のモニターに移動した際も、自動的に画面内に収まるよう比率計算されます。</p></div><h3 id="インラインウィンドウおよびメインウィンドウでのロゴ" tabindex="-1">インラインウィンドウおよびメインウィンドウでのロゴ <a class="header-anchor" href="#インラインウィンドウおよびメインウィンドウでのロゴ" aria-label="Permalink to &quot;インラインウィンドウおよびメインウィンドウでのロゴ&quot;">​</a></h3><ul><li><strong>インラインウィンドウ</strong>：ファイルダイアログ（開く/保存/参照）に埋め込まれている場合、左クリックで <a href="#3-クイックナビゲーションマウス操作"><strong>クイックナビゲーション</strong></a> を表示。通常のエクスプローラーでは装飾表示のみです。ロゴをドラッグするとウィンドウ自体が移動し、そのオフセットは次回以降ドッキングするたびに再適用されます。</li><li><strong>メインウィンドウ</strong>：ロゴを左クリックするとコンテキストメニューを開きます。すでにメインウィンドウを開いているため、メニューでは<strong>メインウィンドウを表示</strong>は非表示になります。中クリックでウィンドウの固定状態を切り替えます。</li></ul><h3 id="検索ボックスのマウス操作-クイックウィンドウ" tabindex="-1">検索ボックスのマウス操作（クイックウィンドウ） <a class="header-anchor" href="#検索ボックスのマウス操作-クイックウィンドウ" aria-label="Permalink to &quot;検索ボックスのマウス操作（クイックウィンドウ）&quot;">​</a></h3><ul><li><strong>ボックス上でホイールを回す</strong>：過去の検索語を後ろ・前へ遡ります。<code>Alt+Up</code> / <code>Alt+Down</code> と同じ移動を、マウスから手を離さずにできます。</li><li><strong>ボックスを中クリック</strong>：現在表示されている履歴項目を削除します。このジェスチャーは固定で、変更可能な <code>Ctrl+Delete</code> の割り当てとは別のものです。</li><li><strong>いつでも文字を入力すると</strong>履歴セッションが終わるため、次のホイール操作は現在の検索語からやり直しになります。履歴はループしません。最も古い語で停止し、最も新しい語まで戻ると最初に始めていた検索語が返ります。</li></ul><h3 id="トレイアイコン" tabindex="-1">トレイアイコン <a class="header-anchor" href="#トレイアイコン" aria-label="Permalink to &quot;トレイアイコン&quot;">​</a></h3><ul><li><strong>左クリック</strong>：クイックウィンドウを表示/非表示します。呼び出しホットキーとまったく同じ動作です。</li><li><strong>右クリック</strong>（ダブルクリック用のハンドラがないため、2 回目のクリックでも開きます）：カーソル位置でメニューを開きます。内容はメインウィンドウの表示、他のデバイスへ送信（LocalSend が有効な間のみ）、ホットキーの有効化/無効化、設定、バージョン情報、クリーン終了（Lertaro だけが実行中のプロセスである場合のみ）、終了です。</li><li><strong>トレイアイコンを隠す</strong>（<a href="./settings/general.html"><strong>設定 → 一般 → システム</strong></a>）を使うとアイコンは消えますが、ウィンドウ内ロゴのメニューまでは消えません。このメニューからホットキーを無効にしている間は、自分で閉じ出せないようアイコンが強制復帰します。</li></ul><h2 id="_3-クイックナビゲーション-マウス操作" tabindex="-1">3. クイックナビゲーション（マウス操作） <a class="header-anchor" href="#_3-クイックナビゲーション-マウス操作" aria-label="Permalink to &quot;3. クイックナビゲーション（マウス操作）&quot;">​</a></h2><p>キーボード入力を行わずに、マウス操作だけで頻繁に使うフォルダーや最近のファイルにアクセスできます。</p><p><a href="./settings/hotkeys-page.html"><strong>設定 → ホットキー</strong></a> で、任意のグローバルキーボードショートカットを割り当てることもできます。デスクトップや通常のアプリではデスクトップのコンテキストでメニューを開き、エクスプローラーやネイティブのファイルダイアログではアクティブなウィンドウのコンテキストを使います。</p><h3 id="呼び出し環境" tabindex="-1">呼び出し環境 <a class="header-anchor" href="#呼び出し環境" aria-label="Permalink to &quot;呼び出し環境&quot;">​</a></h3><ul><li><strong>デスクトップの余白</strong>：中クリック（または左ダブルクリック）でメニューを開き、フォルダーやファイルをクリックして直接開く。</li><li><strong>エクスプローラー</strong>：余白部分を中クリックして開き、クリックしたフォルダーへ現在のウィンドウが即座に移動。</li><li><strong>対応ファイラー</strong>：Directory Opus、Total Commander、XYplorer、Files、One Commander などのファイル一覧部分を中クリック（詳細は <a href="./file-manager-support.html"><strong>対応ファイルマネージャー</strong></a> を参照）。</li><li><strong>ファイルダイアログ</strong>：各種アプリの「開く/保存/フォルダーの参照」ダイアログ内で中クリックまたはロゴをクリック。対象フォルダーへ安全に移動します。</li></ul><h3 id="メニュー構成と管理" tabindex="-1">メニュー構成と管理 <a class="header-anchor" href="#メニュー構成と管理" aria-label="Permalink to &quot;メニュー構成と管理&quot;">​</a></h3><p><strong>階層型フォルダーブラウザー（Folder Cascader）</strong> プラグインによって提供されます。</p><ol><li><strong>現在開いているフォルダー</strong>：サポートされているすべてのファイラーで現在開かれているフォルダーを自動集約・重複排除して一覧表示。</li><li><strong>お気に入り・履歴</strong>：スター付きのお気に入りと最近のアクセス履歴を分類表示。</li><li><strong>カスタム階層フォルダー</strong>：<strong>設定 → プラグイン → Folder Cascader</strong> で独自の階層メニューを作成可能（例: <code>仕事/プロジェクトA</code>）。</li><li><strong>クイックフォルダー登録（<code>+</code> ボタン）</strong>：メニューの各階層ヘッダーにある <code>+</code> ボタンをクリックするだけで、現在開いているフォルダーをそのカテゴリに直接追加可能。</li></ol><h2 id="_4-固定キー-変更不可" tabindex="-1">4. 固定キー（変更不可） <a class="header-anchor" href="#_4-固定キー-変更不可" aria-label="Permalink to &quot;4. 固定キー（変更不可）&quot;">​</a></h2><p>直感的な操作の一貫性を保つため、以下のキー操作はすべての設定で固定されています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">キー</th><th style="text-align:left;">状況</th><th style="text-align:left;">動作</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">結果一覧</td><td style="text-align:left;">選択中の項目（ファイル/フォルダー/アプリ/アクション）を開く。メインウィンドウでは<strong>選択したすべての行</strong>を開く。検索欄が空のインラインウィンドウでは、代わりに検索を終了する（開くべき筆頭結果が存在しないため）。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">結果一覧</td><td style="text-align:left;">エクスプローラーで選択項目の場所を開いてフォーカス。</td></tr><tr><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">結果一覧</td><td style="text-align:left;">選択した項目を管理者権限で実行。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">クイックウィンドウ</td><td style="text-align:left;">ウィンドウを隠す。この 1 回で検索欄が空になることはない。検索語を保持するか捨てるかは、<strong>閉じた後も検索ボックスの内容を保持する</strong> の設定側で決まる。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">メインウィンドウ</td><td style="text-align:left;">検索語をクリアして検索ボックスに再びフォーカスを当てる。検索欄がすでに空ならウィンドウを閉じ、<strong>閉じた後も検索ボックスの内容を保持する</strong> が有効な場合は即座に閉じる（無駄に 2 回押すことはない）。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">インラインウィンドウ</td><td style="text-align:left;">上記の「<strong>インラインウィンドウの呼び出しとフォーカスの引き継ぎ</strong>」を参照。ダイアログがキーボードを持っている間はウィンドウを閉じ、ウィンドウが持っている間はフォーカスを返す。</td></tr><tr><td style="text-align:left;"><code>Escape</code></td><td style="text-align:left;">アクションメニュー</td><td style="text-align:left;">1 回につき 1 階層。まずアクションの絞り込みをクリアし、次にサブメニューから外へ戻り、最後にメニューを出て元の検索語を復元する。</td></tr><tr><td style="text-align:left;"><code>Backspace</code></td><td style="text-align:left;">アクションメニュー</td><td style="text-align:left;">絞り込みテキストが空の状態で押すと、アクションメニューを閉じて結果一覧に戻る。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code> 方向キー</td><td style="text-align:left;">アクションメニュー</td><td style="text-align:left;">左キーで親メニューに戻り、右キーでサブメニューに入る。<code>Tab</code> でもサブメニューに入るが、次の項目/前の項目のホットキーに割り当てている場合はそちらが優先される。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">インラインウィンドウ</td><td style="text-align:left;">検索ボックスからフォーカスが逃げないよう吸収される。一方、ダイアログ側で押した <code>Tab</code> は従来どおりダイアログ自身のコントロールを順に移動する。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">アクションメニュー</td><td style="text-align:left;">選択中のサブメニューに入る。ただし <code>Tab</code> を次の項目/前の項目のホットキーに割り当てている場合はそちらが優先される。</td></tr><tr><td style="text-align:left;"><code>Apps</code> / <code>Shift+F10</code></td><td style="text-align:left;">メインウィンドウ</td><td style="text-align:left;">右クリックとまったく同じく、現在の選択に対するアクションメニューを開く。</td></tr><tr><td style="text-align:left;"><code>Alt+Space</code></td><td style="text-align:left;">Lertaro の全ウィンドウ</td><td style="text-align:left;">誤動作を防ぐため、システムタイトルバーメニューを無効化。</td></tr><tr><td style="text-align:left;"><code>Alt+F4</code></td><td style="text-align:left;">メイン / 設定ウィンドウ</td><td style="text-align:left;">ウィンドウを通常どおり閉じる。クイックウィンドウ・インラインウィンドウ・クイックパネル・プレビュー・LocalSend・アプリ内ダイアログでは無効化。</td></tr></tbody></table><h2 id="_5-プラグインアクションとプロセスブラックリスト" tabindex="-1">5. プラグインアクションとプロセスブラックリスト <a class="header-anchor" href="#_5-プラグインアクションとプロセスブラックリスト" aria-label="Permalink to &quot;5. プラグインアクションとプロセスブラックリスト&quot;">​</a></h2><h3 id="プラグインアクションのホットキー" tabindex="-1">プラグインアクションのホットキー <a class="header-anchor" href="#プラグインアクションのホットキー" aria-label="Permalink to &quot;プラグインアクションのホットキー&quot;">​</a></h3><p>内蔵のファイル操作には次の既定キーが用意されています：切り取り <code>Ctrl+X</code>、ファイルのコピー <code>Ctrl+C</code>、貼り付け <code>Ctrl+V</code>、削除 <code>Delete</code>、完全削除 <code>Shift+Delete</code>、パスコピー <code>Ctrl+Shift+C</code>、名前をコピー <code>Shift+C</code>、エクスプローラーで表示 <code>Ctrl+Enter</code>、管理者として実行 <code>Ctrl+Shift+Enter</code>。</p><p>破壊的なキーを検索ボックスの下で安全に扱うため、2 つの歯止めを設けています。組み合わせキーがアクションに届くのは、検索ボックスに<strong>テキストが選択されていない</strong>ときだけなので、<code>Ctrl+X</code> / <code>Ctrl+C</code> / <code>Ctrl+V</code> はこれまでどおり検索語の切り取り・コピー・貼り付けに使えます。<code>Delete</code> のような修飾キーなしのキーがアクションに届くのは、キャレットが<strong>すでに検索語の末尾</strong>にあるときだけです。そこでは削除すべき文字が残っていませんから、テキストのそれ以外の位置ではこのキーは入力用のキーのままです。さらに、どちらの削除アクションも Shell 自身の <code>IFileOperation</code> を通るため、キーとファイルの間にはネイティブの「ごみ箱へ移動しますか」/「完全に削除しますか」の確認が立ちはだかります。いずれも <strong>設定 → ホットキー → プラグインアクション</strong> で再登録したりクリアしたりできます。</p><h3 id="プロセスブラックリストと全画面自動バイパス" tabindex="-1">プロセスブラックリストと全画面自動バイパス <a class="header-anchor" href="#プロセスブラックリストと全画面自動バイパス" aria-label="Permalink to &quot;プロセスブラックリストと全画面自動バイパス&quot;">​</a></h3><ul><li><strong>全画面アプリの自動バイパス</strong>：フルスクリーンで動作する 3D ゲームや動画プレイヤーを検知すると、Lertaro は自動的にすべてのグローバルホットキーを通過させ、ゲームの操作を妨げません。</li><li><strong>カスタムプロセスブラックリスト</strong>：<a href="./settings/hotkeys-page.html#プロセスブラックリスト"><strong>設定 → ホットキー</strong></a> に特定のプロセス名（例: <code>game.exe</code>）を登録すると、そのアプリがフォアグラウンドにある間はホットキーを完全に無効化します。</li></ul>',38)])])}const h=e(r,[["render",a]]);export{x as __pageData,h as default};
